import { initializeApp } from 'firebase/app';
import { getFirestore, collection, query, orderBy, getDocs, doc, updateDoc, serverTimestamp } from 'firebase/firestore';
import { getAuth } from 'firebase/auth';

const firebaseConfig = {
  apiKey: "AIzaSyBN3IPC7dNXSxC8NMX9tFRFm4jYRUzkbzU",
  authDomain: "medvision-de555.firebaseapp.com",
  projectId: "medvision-de555",
  storageBucket: "medvision-de555.firebasestorage.app",
  messagingSenderId: "941147254074",
  appId: "1:941147254074:web:1ac9721d6c1d31186cb403"
};

const app = initializeApp(firebaseConfig);


export const db = getFirestore(app);
export const auth = getAuth(app);

export { 
collection, 
doc,
getDocs,
orderBy,
query,
serverTimestamp, 
updateDoc
};
